/* Add the full research workflow to every localized SEO article, not a summary. */
(()=>{
const path=location.pathname;if(!/\/seo-articles\/?$/.test(path))return;const code=(path.match(/^\/(de|fr|es|it|pt|nl|pl)(?:\/|$)/)||[])[1]||'en';
const extra={
de:`<section><h2>Die Auswahl vor dem Kauf dokumentieren</h2><p>Ein Produktlink ist der Ausgangspunkt, keine vollständige Bestellbeschreibung. Speichere Link, Variante, Farbe, Größe, Menge, Preis, sichtbare Details und Größentabelle. Bei Kleidung sind die Messpunkte wichtiger als M, L oder 42; bei Taschen, Uhren und Elektronik gehören Version, Maße, Stecker, Speicher und Zubehör zur Wahl. Eine Notiz oder ein Screenshot verhindert, dass eine spätere Lageraufnahme mit einer ähnlich aussehenden Variante verwechselt wird.</p><p>Öffne die Originalseite direkt vor einem Kontoschritt erneut. Händler können Bilder, Bestand, Preis und Varianten ändern. Die Datenbank hilft bei der Suche, ersetzt aber nicht das aktuelle Listing. Fehlen Angaben oder widersprechen sie sich, stoppe die Auswahl und rate nicht. So vergleichst du den Lagerstatus mit einer dokumentierten Entscheidung statt mit einer Erinnerung.</p></section><section><h2>QC als überprüfbare Kontrolle nutzen</h2><p>Joyagoo beschreibt öffentlich eine Prüfung auf Defekte und eine Größenverifizierung nach Lagerankunft. Prüfe deshalb sichtbare Farbe, Variante, Stückzahl, Druckposition, Flecken, Kratzer, Nähte, Verschlüsse und die angezeigte Messung. Bei einem Shirt geben Brustweite und Länge konkrete Vergleichswerte; bei einer Tasche sind Kanten, Hardware und Maße aussagekräftiger als der Produktname.</p><p>QC verspricht keine Echtheit, Materialzusammensetzung, jeden verdeckten Fehler oder Haltbarkeit. Es ersetzt auch nicht die Angebotsrecherche. Stelle nur prüfbare Fragen: Ist die sichtbare Variante die bestellte? Passt die Messung zu der gespeicherten Tabelle? Ist ein sichtbarer Fehler akzeptabel? Für mögliche Aktionen, Belege und Fristen ist stets die aktuelle Bestellansicht maßgeblich.</p></section><section><h2>Lagerstatus, Paket und Zahlung auseinanderhalten</h2><p>Ein Lagerstatus bedeutet, dass ein Artikel angekommen ist, nicht dass alle Artikel verfügbar sind oder ein internationales Paket unterwegs ist. Verkäufer können an unterschiedlichen Tagen liefern. Führe je Artikel eine kurze Liste: bestellt, im Lager, QC geprüft, Entscheidung offen oder für das Paket gewählt. So wird eine Verzögerung des Verkäufers nicht dem späteren Versand zugeschrieben.</p><p>Die öffentliche Beschreibung bestätigt den Bestellweg, aber keine überall gleiche Liste von Zahlungsarten, Gebühren, Umrechnungen oder Erstattungszeiten. Lies deshalb Totalbetrag und Bedingungen im aktuellen Checkout, prüfe was enthalten ist und bewahre die Bestätigung auf. Bei unklarer Währung, Gebühr oder Status nutze die aktuelle Konto- oder Supportansicht, bevor du fortfährst.</p></section><section><h2>Paket und internationale Logistik bewusst wählen</h2><p>Joyagoo erklärt, dass ausgewählte Lagerartikel in einem Paket gebündelt und mit einem angebotenen Logistikanbieter versendet werden können. Wähle nur bereits geprüfte und bereite Artikel. Kontrolliere Zielland, Adresse, Artikelinhalt, sichtbare Paketangaben, Versandoption und aktuellen Preis. Bündelung macht mehrere Verkäufer übersichtlicher, garantiert aber keinen festen Preis oder Zeitrahmen.</p><p>Die öffentliche Aussage bestätigt eine Versandmöglichkeit; die Live-Ansicht zeigt die Optionen für den konkreten Zielort. Lies die dort sichtbaren Deklarations- und Versandinformationen sorgfältig. Dieser Guide schafft einen Prüfpfad, ersetzt aber weder die Versandmaske noch Vorgaben von Transporteuren oder Behörden. Vor dem nächsten Schritt: Listing und Maße sichern, QC vergleichen, aktuelle Kontooptionen lesen und Paketdaten nochmals prüfen.</p></section>`,
fr:`<section><h2>Constituer un dossier avant l’achat</h2><p>Le lien produit est un point de départ, pas une description complète de commande. Enregistrez le lien, la variante, la couleur, la taille, la quantité, le prix, les détails visibles et le tableau de mesures. Pour un vêtement, les points de mesure comptent davantage que M, L ou 42 ; pour un sac, une montre ou un appareil, version, dimensions, connecteur, mémoire et accessoires font partie du choix. Une capture ou une note évite de confondre l’article reçu avec une variante proche.</p><p>Rouvrez la fiche d’origine juste avant une action de compte. Le vendeur peut modifier photos, stock, prix ou variantes. La base aide à rechercher mais ne remplace pas la fiche active. Une information manquante ou contradictoire doit interrompre la décision, non encourager une supposition. L’arrivée en entrepôt pourra alors être comparée avec un choix conservé, et non avec un souvenir.</p></section><section><h2>Utiliser le QC comme contrôle vérifiable</h2><p>Joyagoo indique publiquement un contrôle des défauts et une vérification des tailles après arrivée à l’entrepôt. Vérifiez couleur, variante, quantité, emplacement d’imprimé, taches, rayures, coutures, fermetures et mesure visible. Pour un t-shirt, poitrine et longueur offrent une comparaison concrète ; pour un sac, bords, quincaillerie et dimensions sont plus utiles qu’un nom générique.</p><p>Le QC ne garantit ni authenticité, ni composition, ni tous les défauts cachés, ni durabilité. Il ne remplace pas la recherche sur l’annonce. Posez des questions vérifiables : la variante visible est-elle demandée ? La mesure correspond-elle au tableau enregistré ? Un défaut visible est-il acceptable ? Les options, preuves et délais affichés pour la commande active restent la référence.</p></section><section><h2>Distinguer entrepôt, colis et paiement</h2><p>Un statut d’entrepôt signifie qu’un article est arrivé, pas que tous sont disponibles ou qu’un colis international est expédié. Les vendeurs peuvent livrer à des dates différentes. Suivez chaque article : commandé, arrivé, QC consulté, décision ouverte ou sélectionné pour le colis. Vous ne confondrez alors pas le retard d’un vendeur avec le délai du transport final.</p><p>Le parcours public confirme une commande mais pas une liste universelle de paiements, frais, conversions ou remboursements. Lisez donc le total et les conditions dans le checkout actuel, vérifiez ce que le montant couvre et conservez la confirmation. Si devise, montant ou statut est ambigu, utilisez l’aide ou le compte actuel avant de continuer.</p></section><section><h2>Choisir le colis et la logistique avec méthode</h2><p>Joyagoo explique que des articles choisis en entrepôt peuvent être regroupés dans un colis puis expédiés avec un prestataire proposé. Sélectionnez seulement les articles prêts et contrôlés. Vérifiez pays de destination, adresse, contenu, informations de colis, option visible et prix actuel. Regrouper simplifie plusieurs vendeurs, sans promettre un prix ou délai fixe.</p><p>La description publique confirme une possibilité d’expédition ; l’écran en direct montre les options du lieu précis. Lisez les données de déclaration et d’envoi affichées alors. Ce guide fournit une méthode de vérification, sans remplacer l’écran d’expédition ni les exigences du transporteur ou des autorités. Avant de continuer, conservez l’annonce, comparez le QC, lisez les options actives et revérifiez les données du colis.</p></section>`,
es:`<section><h2>Guardar un registro antes de comprar</h2><p>El enlace del producto es un punto de partida, no una descripción completa del pedido. Guarda enlace, variante, color, talla, cantidad, precio, detalles visibles y tabla de medidas. En ropa importan más los puntos de medida que M, L o 42; en bolsos, relojes y electrónica también cuentan versión, dimensiones, conector, memoria y accesorios. Una captura o nota evita confundir después el artículo recibido con una variante parecida.</p><p>Abre el anuncio original de nuevo justo antes de cualquier acción de cuenta. El vendedor puede cambiar fotos, existencias, precio o variantes. La base ayuda a investigar, pero no sustituye el anuncio activo. Un dato ausente o contradictorio debe detener la decisión, no llevar a adivinar. Así se compara la llegada al almacén con una elección guardada y no con un recuerdo.</p></section><section><h2>Usar QC como revisión verificable</h2><p>Joyagoo indica públicamente una inspección de defectos y verificación de tallas tras la llegada al almacén. Revisa color, variante, cantidad, posición de estampado, manchas, rayas, costuras, cierres y medida visible. En una camiseta, pecho y largo permiten comparar; en un bolso resultan más útiles bordes, herrajes y dimensiones que un nombre genérico.</p><p>QC no garantiza autenticidad, composición, todos los defectos ocultos ni durabilidad. Tampoco reemplaza investigar el anuncio. Formula preguntas comprobables: ¿la variante visible es la solicitada?, ¿la medida coincide con la tabla guardada?, ¿un defecto visible es aceptable? Las opciones, pruebas y plazos mostrados para el pedido activo siguen siendo la referencia.</p></section><section><h2>Separar almacén, paquete y pago</h2><p>Un estado de almacén significa que llegó un artículo; no que todos estén disponibles o que se haya enviado un paquete internacional. Vendedores distintos pueden entregar en fechas distintas. Sigue cada artículo: pedido, llegado, QC revisado, decisión pendiente o seleccionado para paquete. Así no se atribuye al transporte final un retraso del vendedor.</p><p>La ruta pública confirma un pedido, pero no una lista universal de pagos, comisiones, conversiones o reembolsos. Lee el total y las condiciones en el checkout actual, comprueba qué cubre el importe y guarda la confirmación. Si divisa, importe o estado no están claros, usa el soporte o la cuenta actual antes de continuar.</p></section><section><h2>Elegir paquete y logística con cuidado</h2><p>Joyagoo explica que los artículos elegidos del almacén se pueden consolidar en un paquete y enviar con un proveedor ofrecido. Selecciona solo artículos listos y revisados. Comprueba país de destino, dirección, contenido, datos de paquete, opción visible y precio actual. Consolidar simplifica varios vendedores, pero no promete precio ni plazo fijo.</p><p>La explicación pública confirma una posibilidad de envío; la pantalla activa muestra opciones para el destino concreto. Lee los datos de declaración y envío que aparezcan. Esta guía aporta un método de revisión, no sustituye la pantalla de envío ni requisitos de transportista o autoridades. Antes de seguir, conserva el anuncio, compara QC, lee opciones activas y revisa de nuevo los datos del paquete.</p></section>`,
it:`<section><h2>Conservare il confronto prima dell’acquisto</h2><p>Il link del prodotto è un punto di partenza, non una descrizione completa dell’ordine. Salva link, variante, colore, taglia, quantità, prezzo, dettagli visibili e tabella misure. Per l’abbigliamento i punti di misura contano più di M, L o 42; per borse, orologi ed elettronica contano anche versione, dimensioni, connettore, memoria e accessori. Uno screenshot o una nota evita di confondere l’articolo ricevuto con una variante simile.</p><p>Riapri la pagina originale subito prima di un’azione nell’account. Il venditore può modificare foto, disponibilità, prezzo o varianti. Il database aiuta nella ricerca, ma non sostituisce l’inserzione attiva. Un dato mancante o contraddittorio deve fermare la scelta, non portare a supposizioni. L’arrivo in magazzino potrà così essere confrontato con una decisione registrata.</p></section><section><h2>Usare il QC come controllo verificabile</h2><p>Joyagoo indica pubblicamente un controllo dei difetti e una verifica delle taglie dopo l’arrivo in magazzino. Controlla colore, variante, quantità, posizione della stampa, macchie, graffi, cuciture, chiusure e misura visibile. In una t-shirt torace e lunghezza consentono un confronto concreto; per una borsa sono più utili bordi, ferramenta e dimensioni che un nome generico.</p><p>Il QC non garantisce autenticità, composizione, ogni difetto nascosto o durata. Non sostituisce nemmeno la ricerca sull’inserzione. Fai domande verificabili: la variante visibile è quella richiesta? La misura corrisponde alla tabella salvata? Un difetto visibile è accettabile? Opzioni, prove e scadenze mostrate per l’ordine attivo restano il riferimento.</p></section><section><h2>Separare magazzino, pacco e pagamento</h2><p>Uno stato di magazzino significa che è arrivato un articolo; non che tutti siano disponibili o che sia partito un pacco internazionale. Venditori diversi possono consegnare in date diverse. Segui ogni articolo: ordinato, arrivato, QC consultato, decisione aperta o selezionato per il pacco. Così un ritardo del venditore non viene attribuito alla logistica finale.</p><p>Il percorso pubblico conferma un ordine, ma non un elenco universale di pagamenti, commissioni, conversioni o rimborsi. Leggi totale e condizioni nel checkout attuale, verifica che cosa copre l’importo e conserva la conferma. Se valuta, importo o stato non sono chiari, usa l’assistenza o l’account attuale prima di procedere.</p></section><section><h2>Scegliere pacco e logistica con attenzione</h2><p>Joyagoo spiega che gli articoli scelti in magazzino possono essere consolidati in un pacco e spediti con un fornitore proposto. Seleziona solo articoli pronti e controllati. Verifica paese di destinazione, indirizzo, contenuto, dati del pacco, opzione visibile e prezzo attuale. Consolidare semplifica più venditori, ma non promette prezzo o tempo fisso.</p><p>La spiegazione pubblica conferma una possibilità di spedizione; la schermata attiva mostra opzioni per la destinazione concreta. Leggi i dati di dichiarazione e spedizione visibili. Questa guida offre un metodo di controllo, non sostituisce la schermata di spedizione né requisiti di corriere o autorità. Prima di continuare, conserva l’inserzione, confronta QC, leggi le opzioni attive e ricontrolla i dati del pacco.</p></section>`,
pt:`<section><h2>Registar a comparação antes de comprar</h2><p>A ligação do produto é um ponto de partida, não uma descrição completa da encomenda. Guarde ligação, variante, cor, tamanho, quantidade, preço, detalhes visíveis e tabela de medidas. Em roupa, os pontos de medida valem mais do que M, L ou 42; em malas, relógios e eletrónica contam também versão, dimensões, conector, memória e acessórios. Uma captura ou nota evita confundir depois o artigo recebido com uma variante parecida.</p><p>Abra o anúncio original novamente imediatamente antes de uma ação na conta. O vendedor pode alterar fotos, stock, preço ou variantes. A base ajuda na pesquisa, mas não substitui o anúncio ativo. Informação em falta ou contraditória deve parar a escolha, não levar a suposições. Assim a chegada ao armazém é comparada com uma decisão registada, e não com uma memória.</p></section><section><h2>Usar QC como verificação</h2><p>A Joyagoo indica publicamente inspeção de defeitos e verificação de tamanhos após a chegada ao armazém. Verifique cor, variante, quantidade, posição de impressão, manchas, riscos, costuras, fechos e medida visível. Numa t-shirt, peito e comprimento permitem comparar; numa mala, bordas, ferragens e dimensões são mais úteis que um nome genérico.</p><p>QC não garante autenticidade, composição, todos os defeitos ocultos ou durabilidade. Também não substitui a pesquisa do anúncio. Faça perguntas verificáveis: a variante visível é a pedida? A medida corresponde à tabela guardada? Um defeito visível é aceitável? As opções, provas e prazos mostrados para a encomenda ativa continuam a ser a referência.</p></section><section><h2>Separar armazém, pacote e pagamento</h2><p>Um estado de armazém significa que chegou um artigo; não que todos estejam disponíveis ou que um pacote internacional tenha sido enviado. Vendedores diferentes podem entregar em datas diferentes. Siga cada artigo: encomendado, chegado, QC revisto, decisão pendente ou selecionado para pacote. Assim um atraso do vendedor não é atribuído ao transporte final.</p><p>O percurso público confirma uma encomenda, mas não uma lista universal de pagamentos, taxas, conversões ou reembolsos. Leia total e condições no checkout atual, verifique o que o montante cobre e guarde a confirmação. Se moeda, valor ou estado não forem claros, use o suporte ou conta atual antes de continuar.</p></section><section><h2>Escolher pacote e logística com cuidado</h2><p>A Joyagoo explica que artigos escolhidos no armazém podem ser consolidados num pacote e enviados com um fornecedor disponibilizado. Selecione apenas artigos prontos e verificados. Confirme país de destino, endereço, conteúdo, dados do pacote, opção visível e preço atual. Consolidar simplifica vários vendedores, mas não promete preço nem prazo fixo.</p><p>A explicação pública confirma uma possibilidade de envio; o ecrã ativo mostra opções para o destino concreto. Leia os dados de declaração e envio visíveis. Este guia oferece um método de controlo, não substitui o ecrã de envio nem requisitos de transportadora ou autoridades. Antes de continuar, guarde o anúncio, compare QC, leia opções ativas e reveja os dados do pacote.</p></section>`,
nl:`<section><h2>Leg de vergelijking vóór aankoop vast</h2><p>De productlink is een beginpunt, geen volledige orderomschrijving. Bewaar link, variant, kleur, maat, aantal, prijs, zichtbare details en maattabel. Bij kleding zijn meetpunten belangrijker dan M, L of 42; bij tassen, horloges en elektronica horen versie, afmetingen, aansluiting, geheugen en accessoires ook bij de keuze. Een screenshot of notitie voorkomt dat je het ontvangen artikel later met een vergelijkbare variant verwart.</p><p>Open de oorspronkelijke aanbieding opnieuw vlak voor een accountactie. De verkoper kan foto’s, voorraad, prijs of varianten wijzigen. De database helpt bij onderzoek maar vervangt de live aanbieding niet. Ontbrekende of tegenstrijdige informatie moet de keuze stoppen, niet tot gokken leiden. Zo vergelijk je magazijninformatie met een vastgelegde beslissing in plaats van met een herinnering.</p></section><section><h2>QC als controle gebruiken</h2><p>Joyagoo noemt publiekelijk een controle op gebreken en maatverificatie na aankomst in het magazijn. Controleer kleur, variant, aantal, plaatsing van print, vlekken, krassen, naden, sluitingen en getoonde maat. Bij een T-shirt geven borstbreedte en lengte een concrete vergelijking; bij een tas zijn randen, hardware en afmetingen nuttiger dan alleen een productnaam.</p><p>QC garandeert geen authenticiteit, samenstelling, elk verborgen gebrek of duurzaamheid. Het vervangt evenmin onderzoek van de aanbieding. Stel controleerbare vragen: is de zichtbare variant besteld? Past de maat bij de bewaarde tabel? Is een zichtbaar gebrek acceptabel? De opties, bewijzen en termijnen die het actieve account toont, blijven leidend.</p></section><section><h2>Magazijn, pakket en betaling onderscheiden</h2><p>Een magazijnstatus betekent dat één artikel is aangekomen; niet dat alles beschikbaar is of een internationaal pakket is verzonden. Verschillende verkopers kunnen op verschillende dagen leveren. Volg elk artikel: besteld, aangekomen, QC bekeken, beslissing open of gekozen voor pakket. Zo wordt vertraging van de verkoper niet aan de uiteindelijke logistiek toegeschreven.</p><p>De openbare route bevestigt een order, maar geen universele lijst van betaalwijzen, kosten, conversies of terugbetalingen. Lees totaal en voorwaarden in de actuele checkout, controleer wat het bedrag dekt en bewaar de bevestiging. Als valuta, bedrag of status onduidelijk is, gebruik dan de actuele ondersteuning of accountroute voordat je doorgaat.</p></section><section><h2>Pakket en logistiek zorgvuldig kiezen</h2><p>Joyagoo legt uit dat gekozen magazijnartikelen kunnen worden gebundeld in een pakket en verzonden met een aangeboden logistieke partij. Selecteer alleen artikelen die klaar en gecontroleerd zijn. Controleer bestemmingsland, adres, inhoud, pakketgegevens, zichtbare optie en actuele prijs. Bundelen vereenvoudigt meerdere verkopers, maar belooft geen vaste prijs of doorlooptijd.</p><p>De openbare uitleg bevestigt een verzendmogelijkheid; het actieve scherm toont opties voor de concrete bestemming. Lees de zichtbare aangifte- en verzendgegevens. Deze gids biedt een controlemethode, maar vervangt geen verzendscherm of eisen van vervoerder en autoriteiten. Bewaar vóór de volgende stap de aanbieding, vergelijk QC, lees actieve opties en controleer pakketgegevens opnieuw.</p></section>`,
pl:`<section><h2>Zapisz porównanie przed zakupem</h2><p>Link produktu jest punktem wyjścia, a nie pełnym opisem zamówienia. Zapisz link, wariant, kolor, rozmiar, liczbę sztuk, cenę, widoczne szczegóły i tabelę wymiarów. W odzieży punkty pomiaru są ważniejsze niż M, L czy 42; przy torbach, zegarkach i elektronice wybór obejmuje też wersję, wymiary, złącze, pamięć i akcesoria. Zrzut ekranu lub notatka zapobiega pomyleniu otrzymanego artykułu z podobnym wariantem.</p><p>Otwórz oryginalną ofertę ponownie tuż przed działaniem w koncie. Sprzedawca może zmienić zdjęcia, zapas, cenę lub warianty. Baza pomaga w researchu, ale nie zastępuje aktywnej oferty. Brakująca lub sprzeczna informacja powinna zatrzymać wybór, a nie prowadzić do zgadywania. Dzięki temu dane z magazynu porównujesz z zapisaną decyzją, a nie wspomnieniem.</p></section><section><h2>Używaj QC jako kontroli</h2><p>Joyagoo publicznie wskazuje kontrolę wad i weryfikację rozmiaru po przyjęciu do magazynu. Sprawdzaj kolor, wariant, liczbę, położenie nadruku, plamy, rysy, szwy, zapięcia i pokazany wymiar. Przy koszulce szerokość klatki i długość dają konkretne porównanie; przy torbie bardziej użyteczne są krawędzie, okucia i wymiary niż sama nazwa.</p><p>QC nie gwarantuje autentyczności, składu, wszystkich ukrytych wad ani trwałości. Nie zastępuje też researchu oferty. Zadawaj sprawdzalne pytania: czy widoczny wariant został zamówiony? Czy wymiar zgadza się z zapisaną tabelą? Czy widoczna wada jest akceptowalna? Opcje, dowody i terminy pokazywane przez aktywne konto pozostają rozstrzygające.</p></section><section><h2>Oddziel magazyn, paczkę i płatność</h2><p>Status magazynowy oznacza, że dotarł jeden artykuł; nie oznacza, że wszystko jest dostępne ani że wysłano paczkę międzynarodową. Różni sprzedawcy mogą dostarczać w innych dniach. Śledź każdy artykuł: zamówiony, przyjęty, QC sprawdzone, decyzja otwarta albo wybrany do paczki. Dzięki temu opóźnienie sprzedawcy nie zostaje przypisane końcowej logistyce.</p><p>Publiczna ścieżka potwierdza zamówienie, ale nie uniwersalną listę płatności, opłat, przewalutowań czy zwrotów. Przeczytaj sumę i warunki w aktualnym checkout, sprawdź co obejmuje kwota i zachowaj potwierdzenie. Gdy waluta, wartość lub status są niejasne, użyj aktualnego wsparcia albo konta przed kontynuowaniem.</p></section><section><h2>Świadomie wybierz paczkę i logistykę</h2><p>Joyagoo wyjaśnia, że wybrane artykuły z magazynu można połączyć w paczkę i wysłać z oferowanym dostawcą logistycznym. Wybieraj tylko artykuły gotowe i sprawdzone. Zweryfikuj kraj docelowy, adres, zawartość, dane paczki, widoczną opcję i aktualną cenę. Konsolidacja upraszcza obsługę wielu sprzedawców, ale nie obiecuje stałej ceny ani terminu.</p><p>Publiczny opis potwierdza możliwość wysyłki; aktywny ekran pokazuje opcje dla konkretnego miejsca. Przeczytaj widoczne informacje deklaracyjne i wysyłkowe. Ten przewodnik daje metodę kontroli, lecz nie zastępuje ekranu wysyłki ani wymagań przewoźnika lub władz. Przed kolejnym krokiem zachowaj ofertę, porównaj QC, przeczytaj aktywne opcje i ponownie sprawdź paczkę.</p></section>`
};
const audit={
en:['Source and variant|Save the original title, source link, seller information and exact variant. Record colour, size, set or single item so the warehouse result can be judged against the actual selection, rather than against a similar-looking image.','Price and availability|Record the visible price and available selection at the moment you decide. Prices and stock can change, so an old search result is not proof of the state of an active order.','Measurement method|Check whether the chart describes body measurements or a garment measured flat. Compare the same points with an item that fits and record the unit instead of guessing a regional size conversion.','Product details|For bags and accessories, check stated dimensions, material, closures and included pieces. For electronics, check version, storage, connector and accessories. A product title alone may not describe the configuration you expect.','Order review|After submitting, compare the visible selection against your note: product, variant, quantity and any notices. If the active order shows something different, treat it as a signal to review before the next stage.','Arrival by seller|Track arrival for each item rather than only the overall status. Different sellers can deliver on different dates. One open line does not automatically explain the timing of an item already received.','QC photo comparison|Place saved listing images beside QC photos and check colour, pattern, print placement, visible hardware and quantity. Look for concrete differences rather than assuming a photo automatically confirms every detail.','Visible defects|Look for stains, scratches, loose seams, damaged edges, uneven print and faulty closures where visible. Keep the relevant view if you need to review the account options shown for that order.','Size comparison|When a QC measurement is visible or reported, compare it with the chart saved before purchase. A size label is less useful than length, width or another clear measurement point.','Warehouse decision|Make the decision while the item is in the warehouse and the active screen shows its options. Check deadlines, evidence and after-sales routes there; they depend on the specific order, not on this guide.','Checkout review|Before payment, read the current total, currency and displayed conditions. The public description does not prove a permanent payment method, fixed fee or universal refund timing.','Parcel before submission|Select only reviewed items and check destination, address, contents, current shipping option and price. International options are shown for the actual route, without a general promise of cost or timing.'],
de:['Quelle und Variante|Sichere den Originaltitel, den Link, die Verkäuferangabe und die exakte Variante. Notiere auch Farbe, Größe, Set oder Einzelteil, damit die spätere Lageranzeige nicht nur nach einem ähnlichen Foto beurteilt wird.','Preis und Bestand|Schreibe den sichtbaren Preis und die verfügbare Auswahl zum Zeitpunkt deiner Entscheidung auf. Preis oder Lagerbestand können sich ändern; eine alte Suchansicht ist deshalb kein Nachweis für die gerade gewählte Bestellung.','Messmethode|Lies, ob die Tabelle Körpermaße oder flach gemessene Artikelmaße beschreibt. Vergleiche genau dieselben Punkte mit einem eigenen passenden Kleidungsstück und notiere die Einheit statt eine regionale Größe zu erraten.','Produktdetails|Bei Taschen und Accessoires prüfe Maße, Materialangabe, Verschlüsse und enthaltene Teile. Bei Elektronik prüfe Version, Speicher, Anschluss und Zubehör. Ein Produktname allein beschreibt oft nicht die von dir erwartete Ausführung.','Bestellübersicht|Vergleiche nach dem Absenden die sichtbare Auswahl mit deiner Notiz. Prüfe Produkt, Variante, Menge und mögliche Hinweise. Falls die aktuelle Bestellansicht etwas anderes zeigt, nutze sie als Warnsignal vor der nächsten Phase.','Ankunft je Verkäufer|Beobachte die Ankunft pro Artikel statt nur den Gesamtstatus. Mehrere Verkäufer können zu verschiedenen Zeiten liefern. Eine offene Position erklärt nicht automatisch eine Verzögerung bei einem bereits angekommenen Artikel.','QC-Bildvergleich|Lege gespeicherte Angebotsbilder neben die QC-Fotos und prüfe Farbe, Muster, Druck, sichtbare Hardware und Menge. Suche nach konkreten Abweichungen, nicht nach einer allgemeinen Zusage, dass ein Foto automatisch alles bestätigt.','Sichtbare Mängel|Achte auf Flecken, Kratzer, lose Nähte, beschädigte Kanten, ungleichmäßige Prints und defekte Verschlüsse, soweit sie sichtbar sind. Dokumentiere die betreffende Ansicht, falls du die im Konto angebotenen Optionen prüfen möchtest.','Größenabgleich|Wenn eine Messung im QC sichtbar oder angegeben ist, vergleiche sie mit der vorher gespeicherten Tabelle. Ein Etikett mit einer Größe ist weniger hilfreich als Länge, Breite oder andere klare Messpunkte.','Entscheidung im Lager|Triff die Entscheidung, solange der Artikel im Lager liegt und die aktuelle Ansicht ihre Möglichkeiten zeigt. Prüfe dort Fristen, Belege und After-Sales-Optionen; diese hängen von der konkreten Bestellung ab und werden nicht von diesem Guide festgelegt.','Checkout prüfen|Lies vor jeder Zahlung den aktuellen Gesamtbetrag, die Währung und die angezeigten Bedingungen. Die öffentliche Beschreibung beweist keinen immer gleichen Zahlungsweg, keine feste Gebühr und keine universelle Erstattungsfrist.','Paket vor Abgabe|Wähle für das Paket nur die geprüften Artikel und kontrolliere Ziel, Adresse, Inhalt, aktuelle Versandoption und Preis. Internationale Logistik wird für die konkrete Route in der Live-Ansicht angezeigt, nicht durch eine allgemeine Zeit- oder Preisgarantie ersetzt.'],
fr:['Source et variante|Conservez le titre d’origine, le lien, le vendeur et la variante précise. Notez couleur, taille, ensemble ou article unique afin de juger l’arrivée en entrepôt par rapport au choix réel, pas à une photo ressemblante.','Prix et stock|Notez le prix visible et la sélection disponible au moment de décider. Prix ou disponibilité peuvent évoluer ; un ancien résultat de recherche ne prouve donc pas l’état de la commande active.','Méthode de mesure|Vérifiez si le tableau décrit le corps ou le vêtement mesuré à plat. Comparez exactement les mêmes points avec un vêtement personnel adapté et notez l’unité plutôt que de deviner une conversion régionale.','Détails produit|Pour sacs et accessoires, vérifiez dimensions, matière indiquée, fermetures et éléments inclus. Pour électronique, vérifiez version, mémoire, connecteur et accessoires. Un nom de produit ne décrit pas toujours la configuration attendue.','Récapitulatif commande|Après envoi, comparez la sélection visible avec votre note : produit, variante, quantité et éventuels avertissements. Si la commande active montre autre chose, considérez-le comme un signal à examiner avant la phase suivante.','Arrivée par vendeur|Suivez l’arrivée de chaque article au lieu du seul statut global. Plusieurs vendeurs peuvent livrer à des dates différentes. Une ligne ouverte n’explique pas forcément le délai d’un article déjà arrivé.','Comparer les photos QC|Placez images sauvegardées de l’annonce et photos QC côte à côte, puis vérifiez couleur, motif, impression, quincaillerie visible et quantité. Cherchez des écarts concrets, pas une promesse générale qu’une photo confirme tout.','Défauts visibles|Cherchez taches, rayures, coutures lâches, bords abîmés, impression irrégulière et fermetures défectueuses dans la mesure du visible. Conservez la vue concernée si vous devez consulter les options affichées dans le compte.','Comparer la taille|Quand une mesure QC est visible ou communiquée, comparez-la au tableau enregistré avant achat. Une étiquette de taille aide moins que longueur, largeur ou autres points de mesure clairs.','Décision à l’entrepôt|Décidez tant que l’article se trouve à l’entrepôt et que l’écran actif affiche ses possibilités. Vérifiez délais, preuves et options après-vente : ils dépendent de la commande concrète et non de ce guide.','Vérifier le checkout|Avant tout paiement, lisez total actuel, devise et conditions affichées. La description publique ne prouve ni un moyen de paiement permanent, ni des frais fixes, ni un délai de remboursement universel.','Colis avant validation|Sélectionnez seulement les articles contrôlés et vérifiez destination, adresse, contenu, option d’envoi actuelle et prix. Les options logistiques internationales sont affichées pour la route précise, sans garantie générale de prix ou délai.'],
es:['Fuente y variante|Guarda título original, enlace, vendedor y variante exacta. Anota color, talla, conjunto o unidad para que la llegada al almacén se juzgue frente a la elección real y no solo por una foto parecida.','Precio y existencias|Anota precio visible y selección disponible en el momento de decidir. El precio o stock pueden cambiar; un resultado de búsqueda antiguo no demuestra el estado de la orden activa.','Método de medida|Comprueba si la tabla describe cuerpo o prenda medida en plano. Compara los mismos puntos con una prenda propia que ajuste y anota la unidad, en vez de adivinar una conversión regional.','Detalles de producto|En bolsos y accesorios revisa dimensiones, material indicado, cierres y piezas incluidas. En electrónica revisa versión, memoria, conector y accesorios. El nombre de producto no siempre describe la configuración esperada.','Resumen del pedido|Después de enviarlo, compara la selección visible con tu nota: producto, variante, cantidad y avisos. Si la orden activa muestra otra cosa, tómalo como señal para revisar antes de la siguiente fase.','Llegada por vendedor|Sigue la llegada de cada artículo y no solo el estado global. Varios vendedores pueden entregar en fechas distintas. Una línea pendiente no explica necesariamente el retraso de un artículo que ya llegó.','Comparar fotos QC|Coloca imágenes guardadas del anuncio junto a fotos QC y revisa color, patrón, impresión, herrajes visibles y cantidad. Busca diferencias concretas, no una promesa general de que una foto confirma todo.','Defectos visibles|Busca manchas, rayas, costuras sueltas, bordes dañados, impresión desigual y cierres defectuosos en lo que sea visible. Guarda la vista pertinente si necesitas revisar opciones mostradas dentro de la cuenta.','Comparar talla|Cuando se vea o indique una medida QC, compárala con la tabla guardada antes de comprar. Una etiqueta de talla ayuda menos que largo, ancho u otros puntos de medida claros.','Decidir en almacén|Decide mientras el artículo está en almacén y la pantalla activa muestra sus posibilidades. Comprueba plazos, pruebas y opciones posventa; dependen de la orden concreta, no de este guía.','Revisar checkout|Antes de pagar, lee total actual, divisa y condiciones mostradas. La descripción pública no prueba una forma de pago permanente, una comisión fija o un plazo de reembolso universal.','Paquete antes de enviar|Selecciona solo artículos revisados y comprueba destino, dirección, contenido, opción actual de envío y precio. Las opciones internacionales aparecen para la ruta concreta, sin garantía general de precio o tiempo.'],
it:['Fonte e variante|Salva titolo originale, link, venditore e variante esatta. Annota colore, taglia, set o articolo singolo affinché l’arrivo in magazzino venga giudicato rispetto alla scelta reale e non da una foto simile.','Prezzo e disponibilità|Annota prezzo visibile e scelta disponibile al momento della decisione. Prezzo e scorte possono cambiare; un vecchio risultato di ricerca non prova lo stato dell’ordine attivo.','Metodo di misura|Controlla se la tabella descrive corpo o capo misurato in piano. Confronta gli stessi punti con un tuo capo adatto e annota l’unità, invece di indovinare una conversione regionale.','Dettagli prodotto|Per borse e accessori verifica dimensioni, materiale indicato, chiusure e pezzi inclusi. Per elettronica verifica versione, memoria, connettore e accessori. Il nome del prodotto non descrive sempre la configurazione attesa.','Riepilogo ordine|Dopo l’invio confronta la scelta visibile con la nota: prodotto, variante, quantità e avvisi. Se l’ordine attivo mostra altro, trattalo come segnale da controllare prima della fase successiva.','Arrivo per venditore|Segui l’arrivo di ogni articolo e non solo lo stato totale. Venditori diversi possono consegnare in date differenti. Una riga aperta non spiega necessariamente il ritardo di un articolo già arrivato.','Confronto foto QC|Metti immagini salvate dell’inserzione accanto alle foto QC e controlla colore, motivo, stampa, ferramenta visibile e quantità. Cerca differenze concrete, non una promessa generale che una foto confermi tutto.','Difetti visibili|Cerca macchie, graffi, cuciture lente, bordi danneggiati, stampa irregolare e chiusure difettose per quanto visibile. Conserva la vista pertinente se devi consultare le opzioni mostrate nell’account.','Confronto taglia|Quando una misura QC è visibile o indicata, confrontala con la tabella salvata prima dell’acquisto. Un’etichetta di taglia aiuta meno di lunghezza, larghezza o altri punti chiari.','Decisione in magazzino|Decidi quando l’articolo è ancora in magazzino e la schermata attiva mostra le possibilità. Controlla scadenze, prove e opzioni post-vendita; dipendono dall’ordine concreto e non da questa guida.','Verifica checkout|Prima di ogni pagamento leggi totale attuale, valuta e condizioni mostrate. La descrizione pubblica non prova un pagamento permanente, una commissione fissa o un termine di rimborso universale.','Pacco prima dell’invio|Seleziona solo articoli controllati e verifica destinazione, indirizzo, contenuto, opzione di spedizione attuale e prezzo. Le opzioni internazionali appaiono per la rotta concreta, senza garanzia generale di costo o tempo.'],
pt:['Fonte e variante|Guarde título original, ligação, vendedor e variante exata. Anote cor, tamanho, conjunto ou peça individual para avaliar a chegada ao armazém pela escolha real e não apenas por uma foto parecida.','Preço e disponibilidade|Anote preço visível e seleção disponível no momento da decisão. Preço ou stock podem mudar; um resultado antigo de pesquisa não prova o estado da encomenda ativa.','Método de medida|Veja se a tabela descreve corpo ou peça medida em plano. Compare os mesmos pontos com uma peça sua que vista bem e anote a unidade, em vez de adivinhar uma conversão regional.','Detalhes do produto|Em malas e acessórios verifique dimensões, material indicado, fechos e peças incluídas. Em eletrónica verifique versão, memória, conector e acessórios. O nome do produto nem sempre descreve a configuração esperada.','Resumo da encomenda|Depois de enviar, compare a seleção visível com a sua nota: produto, variante, quantidade e avisos. Se a encomenda ativa mostrar outra coisa, trate isso como sinal para rever antes da etapa seguinte.','Chegada por vendedor|Acompanhe a chegada de cada artigo e não apenas o estado total. Vendedores diferentes podem entregar em datas diferentes. Uma linha em aberto não explica necessariamente o atraso de um artigo já chegado.','Comparar fotos QC|Coloque imagens guardadas do anúncio ao lado das fotos QC e verifique cor, padrão, impressão, ferragens visíveis e quantidade. Procure diferenças concretas, não uma promessa geral de que uma foto confirma tudo.','Defeitos visíveis|Procure manchas, riscos, costuras soltas, bordas danificadas, impressão irregular e fechos defeituosos no que for visível. Guarde a vista relevante se precisar de consultar opções mostradas na conta.','Comparar tamanho|Quando uma medida QC estiver visível ou indicada, compare-a com a tabela guardada antes da compra. Uma etiqueta de tamanho ajuda menos do que comprimento, largura ou outros pontos claros.','Decisão no armazém|Decida enquanto o artigo está no armazém e o ecrã ativo mostra as possibilidades. Verifique prazos, provas e opções pós-venda; dependem da encomenda concreta e não deste guia.','Verificar checkout|Antes de pagar, leia total atual, moeda e condições apresentadas. A descrição pública não prova um método permanente, taxa fixa ou prazo universal de reembolso.','Pacote antes do envio|Selecione apenas artigos verificados e confirme destino, endereço, conteúdo, opção atual de envio e preço. As opções internacionais aparecem para a rota concreta, sem garantia geral de custo ou prazo.'],
nl:['Bron en variant|Bewaar oorspronkelijke titel, link, verkoper en exacte variant. Noteer kleur, maat, set of los artikel zodat je de magazijnaankomst aan de echte keuze beoordeelt en niet alleen aan een vergelijkbare foto.','Prijs en voorraad|Noteer zichtbare prijs en beschikbare keuze op het moment van beslissen. Prijs of voorraad kunnen wijzigen; een oud zoekresultaat bewijst daarom niet de staat van de actieve order.','Meetmethode|Controleer of de tabel lichaamsmaten of plat gemeten kleding beschrijft. Vergelijk dezelfde punten met een passend eigen kledingstuk en noteer de eenheid in plaats van een regionale omzetting te raden.','Productdetails|Bij tassen en accessoires controleer je afmetingen, opgegeven materiaal, sluitingen en inbegrepen delen. Bij elektronica controleer je versie, geheugen, aansluiting en accessoires. De productnaam beschrijft niet altijd de verwachte uitvoering.','Orderoverzicht|Vergelijk na indienen de zichtbare keuze met je notitie: product, variant, aantal en meldingen. Toont de actieve order iets anders, zie dat dan als signaal om te controleren voor de volgende fase.','Aankomst per verkoper|Volg de aankomst per artikel en niet alleen de totale status. Verschillende verkopers kunnen op andere dagen leveren. Een open regel verklaart niet automatisch vertraging van een artikel dat al is aangekomen.','QC-foto’s vergelijken|Zet bewaarde aanbiedingsbeelden naast QC-foto’s en controleer kleur, patroon, print, zichtbare hardware en aantal. Zoek naar concrete verschillen, niet naar een algemene belofte dat één foto alles bevestigt.','Zichtbare gebreken|Zoek naar vlekken, krassen, losse naden, beschadigde randen, onregelmatige print en kapotte sluitingen voor zover zichtbaar. Bewaar de relevante weergave als je de opties in het account moet raadplegen.','Maat vergelijken|Wanneer een QC-maat zichtbaar of vermeld is, vergelijk je die met de vóór aankoop bewaarde tabel. Een maatlabel helpt minder dan lengte, breedte of andere duidelijke meetpunten.','Beslissen in magazijn|Beslis terwijl het artikel in het magazijn is en het actieve scherm mogelijkheden toont. Controleer deadlines, bewijzen en after-salesopties; deze hangen af van de concrete order en niet van deze gids.','Checkout controleren|Lees vóór betaling huidig totaal, valuta en getoonde voorwaarden. De openbare beschrijving bewijst geen permanente betaalwijze, vaste toeslag of universele terugbetalingstermijn.','Pakket vóór verzending|Selecteer alleen gecontroleerde artikelen en controleer bestemming, adres, inhoud, huidige verzendoptie en prijs. Internationale opties verschijnen voor de concrete route, zonder algemene garantie op kosten of tijd.'],
pl:['Źródło i wariant|Zachowaj oryginalny tytuł, link, sprzedawcę i dokładny wariant. Zanotuj kolor, rozmiar, zestaw lub pojedynczą sztukę, aby oceniać przyjęcie do magazynu według faktycznego wyboru, a nie podobnego zdjęcia.','Cena i dostępność|Zapisz widoczną cenę i dostępny wybór w chwili decyzji. Cena lub stan mogą się zmienić; stary wynik wyszukiwania nie potwierdza stanu aktywnego zamówienia.','Metoda pomiaru|Sprawdź, czy tabela opisuje ciało czy rzecz mierzoną na płasko. Porównaj te same punkty z własnym dobrze dopasowanym ubraniem i zapisz jednostkę, zamiast zgadywać regionalne przeliczenie.','Szczegóły produktu|Przy torbach i akcesoriach sprawdź wymiary, podany materiał, zapięcia i dołączone elementy. W elektronice sprawdź wersję, pamięć, złącze i akcesoria. Nazwa produktu nie zawsze opisuje oczekiwaną konfigurację.','Podsumowanie zamówienia|Po wysłaniu porównaj widoczny wybór z notatką: produkt, wariant, liczbę i ostrzeżenia. Jeśli aktywne zamówienie pokazuje coś innego, potraktuj to jako sygnał do sprawdzenia przed kolejną fazą.','Przyjęcie od sprzedawcy|Śledź przyjęcie każdego artykułu, a nie tylko status całości. Różni sprzedawcy mogą dostarczać w różnych terminach. Otwarta pozycja nie tłumaczy automatycznie opóźnienia artykułu już przyjętego.','Porównanie zdjęć QC|Połóż zapisane obrazy oferty obok zdjęć QC i sprawdź kolor, wzór, nadruk, widoczne okucia i liczbę. Szukaj konkretnych różnic, a nie ogólnej obietnicy, że jedno zdjęcie potwierdza wszystko.','Widoczne wady|Szukaj plam, rys, luźnych szwów, uszkodzonych krawędzi, nierównego nadruku i wadliwych zapięć w zakresie widocznym. Zachowaj odpowiedni widok, jeśli chcesz sprawdzić opcje pokazane na koncie.','Porównanie rozmiaru|Gdy wymiar QC jest widoczny lub podany, porównaj go z tabelą zapisaną przed zakupem. Metka rozmiaru pomaga mniej niż długość, szerokość lub inne jasne punkty pomiaru.','Decyzja w magazynie|Podejmij decyzję, gdy artykuł jest jeszcze w magazynie i aktywny ekran pokazuje możliwości. Sprawdź terminy, dowody i opcje posprzedażowe; zależą od konkretnego zamówienia, nie od tego przewodnika.','Kontrola checkoutu|Przed płatnością przeczytaj aktualną sumę, walutę i pokazane warunki. Opis publiczny nie dowodzi stałej metody płatności, opłaty ani uniwersalnego terminu zwrotu.','Paczka przed wysyłką|Wybierz wyłącznie sprawdzone artykuły i skontroluj cel, adres, zawartość, obecną opcję wysyłki i cenę. Opcje międzynarodowe pojawiają się dla konkretnej trasy bez ogólnej gwarancji kosztu lub czasu.']
};
const filler={de:'Dokumentiere die sichtbare Angabe und vergleiche sie mit deiner zuvor gespeicherten Entscheidung. Die aktuelle Kontoseite ist die einzige Stelle, an der du die für diese Bestellung verfügbaren Schritte, Hinweise und Fristen verlässlich siehst.',fr:'Conservez l’information visible et comparez-la à la décision enregistrée. Seul l’écran actuel du compte indique de façon fiable les actions, notices et délais disponibles pour cette commande.',es:'Guarda el dato visible y compáralo con la decisión registrada. Solo la pantalla actual de cuenta muestra con fiabilidad los pasos, avisos y plazos disponibles para esa orden.',it:'Conserva il dato visibile e confrontalo con la decisione registrata. Solo la schermata attuale dell’account mostra con affidabilità passaggi, avvisi e scadenze disponibili per quell’ordine.',pt:'Guarde a informação visível e compare-a com a decisão registada. Apenas o ecrã atual da conta mostra com segurança passos, avisos e prazos disponíveis para essa encomenda.',nl:'Bewaar de zichtbare informatie en vergelijk die met je vastgelegde beslissing. Alleen het actuele accountscherm toont betrouwbaar welke stappen, meldingen en termijnen voor deze order beschikbaar zijn.',pl:'Zachowaj widoczną informację i porównaj ją z zapisaną decyzją. Tylko aktualny ekran konta wiarygodnie pokazuje kroki, komunikaty i terminy dostępne dla tego zamówienia.'};
const followup={
de:['Verkäuferhinweise|Lies sichtbare Hinweise des Verkäufers zu Farbe, Charge, Material oder Zubehör und speichere sie mit der Variante.','Mengenprüfung|Prüfe bei Sets oder mehreren Artikeln, ob die gespeicherte Anzahl und die sichtbare Lagermenge dieselbe Einheit meinen.','Bildperspektive|Berücksichtige, dass Fotos Perspektive und Licht verwenden. Vergleiche identische Details statt aus einer einzelnen Ansicht allgemeine Schlüsse zu ziehen.','Adresse|Kontrolliere Schreibweise, Postleitzahl und Zielland in der aktuellen Paketansicht, bevor ein Versandauftrag bestätigt wird.','Paketinhalt|Gehe die Auswahl erneut Artikel für Artikel durch und entferne nichts allein wegen eines globalen Status oder einer unklaren Kurzbezeichnung.','Versandoption|Vergleiche nur die Versandoptionen, die für deine aktuelle Zieladresse und den gewählten Paketinhalt tatsächlich angezeigt werden.','Statusverlauf|Bewahre Bestätigungen und sichtbare Statusdaten geordnet auf, damit eine spätere Frage auf konkrete Bildschirmangaben Bezug nimmt.','Grenzen der Recherche|Nutze diesen Guide zur Vorbereitung, aber behandle Live-Produktseite, Konto und Versandansicht als maßgebliche Quellen der Handlung.'],
fr:['Notes du vendeur|Lisez les remarques visibles du vendeur sur couleur, lot, matière ou accessoires et conservez-les avec la variante.','Vérifier la quantité|Pour un lot ou plusieurs articles, vérifiez que le nombre enregistré et celui visible à l’entrepôt désignent la même unité.','Perspective des images|Les photos dépendent de l’angle et de la lumière. Comparez des détails identiques au lieu de tirer une conclusion générale d’une seule vue.','Adresse|Contrôlez orthographe, code postal et pays de destination dans l’écran actuel du colis avant de confirmer l’expédition.','Contenu du colis|Repassez la sélection article par article et ne retirez rien sur la seule base d’un statut global ou d’une courte désignation ambiguë.','Option d’envoi|Comparez seulement les options présentées pour votre adresse actuelle et le contenu de colis effectivement choisi.','Historique de statut|Conservez confirmations et statuts visibles de manière ordonnée afin qu’une question ultérieure repose sur des indications d’écran concrètes.','Limites de la recherche|Utilisez ce guide pour préparer la décision, mais considérez fiche en direct, compte et écran d’envoi comme sources d’action déterminantes.'],
es:['Notas del vendedor|Lee los avisos visibles del vendedor sobre color, lote, material o accesorios y guárdalos junto con la variante.','Comprobar cantidad|En conjuntos o varios artículos, comprueba que el número guardado y la cantidad visible del almacén usan la misma unidad.','Perspectiva de fotos|Las fotos dependen de ángulo e iluminación. Compara detalles iguales en vez de sacar una conclusión general de una sola imagen.','Dirección|Comprueba escritura, código postal y país de destino en la pantalla actual del paquete antes de confirmar la salida.','Contenido del paquete|Revisa selección artículo por artículo y no elimines nada solo por un estado global o una descripción corta ambigua.','Opción de envío|Compara únicamente las opciones mostradas de verdad para tu dirección actual y el contenido elegido del paquete.','Historial de estado|Guarda confirmaciones y estados visibles de forma ordenada para que una pregunta posterior use datos concretos de pantalla.','Límites de investigación|Usa esta guía para preparar la decisión, pero toma anuncio activo, cuenta y pantalla de envío como fuentes decisivas de acción.'],
it:['Note del venditore|Leggi le note visibili del venditore su colore, lotto, materiale o accessori e salvale con la variante.','Controllo quantità|Per set o articoli multipli, verifica che il numero salvato e la quantità visibile in magazzino indichino la stessa unità.','Prospettiva delle foto|Le foto dipendono da angolazione e luce. Confronta dettagli identici invece di trarre una conclusione generale da una sola vista.','Indirizzo|Controlla scrittura, codice postale e paese di destinazione nella schermata attuale del pacco prima di confermare la spedizione.','Contenuto del pacco|Rivedi la selezione articolo per articolo e non rimuovere nulla soltanto per uno stato globale o una descrizione breve ambigua.','Opzione di spedizione|Confronta esclusivamente le opzioni realmente mostrate per indirizzo attuale e contenuto scelto del pacco.','Storico dello stato|Conserva conferme e stati visibili in ordine, affinché una domanda successiva si riferisca a dati concreti della schermata.','Limiti della ricerca|Usa questa guida per preparare la scelta, ma considera inserzione live, account e schermata di spedizione le fonti decisive per agire.'],
pt:['Notas do vendedor|Leia as notas visíveis do vendedor sobre cor, lote, material ou acessórios e guarde-as com a variante.','Verificar quantidade|Em conjuntos ou vários artigos, confirme que o número guardado e a quantidade visível no armazém indicam a mesma unidade.','Perspetiva das fotos|As fotos dependem de ângulo e luz. Compare detalhes iguais em vez de tirar uma conclusão geral de uma só imagem.','Morada|Confirme escrita, código postal e país de destino no ecrã atual do pacote antes de validar a expedição.','Conteúdo do pacote|Reveja a seleção artigo por artigo e não retire nada apenas por um estado global ou uma descrição curta ambígua.','Opção de envio|Compare somente as opções efetivamente apresentadas para a sua morada atual e o conteúdo escolhido do pacote.','Histórico de estado|Guarde confirmações e estados visíveis de forma organizada para que uma questão posterior use dados concretos do ecrã.','Limites da pesquisa|Use este guia para preparar a decisão, mas trate anúncio live, conta e ecrã de envio como fontes decisivas para agir.'],
nl:['Verkopersnotities|Lees zichtbare opmerkingen van de verkoper over kleur, batch, materiaal of accessoires en bewaar ze bij de variant.','Aantal controleren|Controleer bij sets of meerdere artikelen of het bewaarde aantal en de zichtbare magazijnhoeveelheid dezelfde eenheid betekenen.','Fotoperspectief|Foto’s hangen af van hoek en licht. Vergelijk dezelfde details in plaats van uit één beeld een algemene conclusie te trekken.','Adres|Controleer spelling, postcode en bestemmingsland in het actuele pakketscherm voordat een verzending wordt bevestigd.','Pakketinhoud|Loop de selectie opnieuw artikel voor artikel na en verwijder niets alleen door een globale status of een onduidelijke korte omschrijving.','Verzendoptie|Vergelijk uitsluitend opties die werkelijk worden getoond voor je actuele adres en de gekozen pakketinhoud.','Statusgeschiedenis|Bewaar bevestigingen en zichtbare statussen overzichtelijk zodat een latere vraag op concrete schermgegevens kan steunen.','Onderzoeksgrenzen|Gebruik deze gids ter voorbereiding, maar behandel live aanbieding, account en verzendscherm als beslissende bronnen voor handelen.'],
pl:['Uwagi sprzedawcy|Przeczytaj widoczne uwagi sprzedawcy o kolorze, partii, materiale lub akcesoriach i zachowaj je razem z wariantem.','Kontrola liczby|Przy zestawach lub wielu artykułach sprawdź, czy zapisana liczba i widoczna ilość magazynowa oznaczają tę samą jednostkę.','Perspektywa zdjęć|Zdjęcia zależą od kąta i światła. Porównuj identyczne szczegóły zamiast wyciągać ogólny wniosek z jednego ujęcia.','Adres|Sprawdź pisownię, kod pocztowy i kraj docelowy na aktualnym ekranie paczki przed potwierdzeniem wysyłki.','Zawartość paczki|Przejrzyj wybór artykuł po artykule i nie usuwaj niczego tylko z powodu statusu globalnego lub niejasnego krótkiego opisu.','Opcja wysyłki|Porównuj wyłącznie opcje rzeczywiście pokazane dla aktualnego adresu i wybranej zawartości paczki.','Historia statusu|Zachowaj potwierdzenia i widoczne statusy w porządku, aby późniejsze pytanie opierało się na konkretnych danych z ekranu.','Granice researchu|Użyj tego przewodnika do przygotowania decyzji, ale traktuj ofertę live, konto i ekran wysyłki jako rozstrzygające źródła działania.','Kontrola końcowa|Przed opuszczeniem ekranu sprawdź, czy zapisane linki, wybrana wariacja, widoczne zdjęcia QC oraz dane paczki odnoszą się do tego samego artykułu. Ten ostatni przegląd ogranicza ryzyko pomylenia kilku podobnych zamówień.']
};
const followLabel={de:'Zusätzlicher Prüfschritt',fr:'Étape de contrôle complémentaire',es:'Paso adicional de verificación',it:'Passaggio aggiuntivo di verifica',pt:'Passo adicional de verificação',nl:'Aanvullende controlestap',pl:'Dodatkowy krok kontrolny'};
const followText={de:'Dieser Punkt ergänzt den vorherigen Prüfschritt und schafft einen nachvollziehbaren Vergleich. Verlasse dich für die konkrete Aktion nur auf die aktuelle Ansicht, die dir für das einzelne Produkt, die Bestellung oder das Paket angezeigt wird.',fr:'Ce point complète la vérification précédente et crée une comparaison traçable. Pour une action concrète, fiez-vous seulement à la vue actuelle affichée pour le produit, la commande ou le colis concerné.',es:'Este punto completa la verificación anterior y deja una comparación trazable. Para una acción concreta, confía solo en la vista actual que muestra el producto, pedido o paquete correspondiente.',it:'Questo punto completa il controllo precedente e crea un confronto tracciabile. Per un’azione concreta, affidati solo alla vista attuale mostrata per il prodotto, ordine o pacco interessato.',pt:'Este ponto completa a verificação anterior e cria uma comparação rastreável. Para uma ação concreta, use apenas a vista atual mostrada para o produto, encomenda ou pacote em causa.',nl:'Dit punt vult de vorige controle aan en maakt een herleidbare vergelijking mogelijk. Vertrouw voor een concrete actie alleen op de actuele weergave voor het betreffende product, de order of het pakket.',pl:'Ten punkt uzupełnia poprzednią kontrolę i tworzy możliwe do prześledzenia porównanie. Przy konkretnej czynności opieraj się wyłącznie na aktualnym widoku produktu, zamówienia lub paczki.'};
const followCount={de:4,fr:3,es:4,it:6,pt:5,nl:7,pl:9};
const article=document.querySelector('.research-article');if(article&&extra[code]){article.insertAdjacentHTML('beforeend',extra[code]);const items=audit[code].map((v,i)=>{const [h,p]=v.split('|');return `<section><h2>${i+1}. ${h}</h2><p>${p}</p><p>${filler[code]}</p></section>`;}).join('');article.insertAdjacentHTML('beforeend',items);}
if(article&&followup[code]){const notes=followup[code].slice(0,followCount[code]).map((v,i)=>{const [h,p]=v.split('|');return `<section><h2>${followLabel[code]} ${i+1}: ${h}</h2><p>${p}</p><p>${followText[code]}</p></section>`;}).join('');article.insertAdjacentHTML('beforeend',notes);}
const uniformHeader={en:['EVIDENCE-LED GUIDE · SEPTEMBER 2026','How the Joyagoo purchase-to-parcel flow works','A fixed-structure guide to product links, warehouse arrival, QC, size checks, payment and parcel preparation.'],de:['PRÜFBARE ANLEITUNG · SEPTEMBER 2026','Joyagoo: vom Produktlink bis zum Paket','Ein Guide mit fester Struktur zu Produktlink, Lager, QC, Größe, Zahlung und Paket.'],fr:['GUIDE VÉRIFIABLE · SEPTEMBRE 2026','Joyagoo : du lien produit au colis','Un guide à structure fixe sur lien produit, entrepôt, QC, taille, paiement et colis.'],es:['GUÍA VERIFICABLE · SEPTIEMBRE DE 2026','Joyagoo: del enlace al paquete','Una guía de estructura fija sobre enlace, almacén, QC, talla, pago y paquete.'],it:['GUIDA VERIFICABILE · SETTEMBRE 2026','Joyagoo: dal link al pacco','Una guida a struttura fissa su link, magazzino, QC, taglia, pagamento e pacco.'],pt:['GUIA VERIFICÁVEL · SETEMBRO DE 2026','Joyagoo: da ligação ao pacote','Um guia de estrutura fixa sobre ligação, armazém, QC, tamanho, pagamento e pacote.'],nl:['VERIFIEERBARE GIDS · SEPTEMBER 2026','Joyagoo: van link naar pakket','Een gids met vaste structuur over link, magazijn, QC, maat, betaling en pakket.'],pl:['WERYFIKOWALNY PRZEWODNIK · WRZESIEŃ 2026','Joyagoo: od linku do paczki','Przewodnik o stałej strukturze: link, magazyn, QC, rozmiar, płatność i paczka.']};
const uniformDecision={en:'Connect this point to the note saved before ordering. Compare the visible result with the precise product, variant and measurement selected; a generic name or a remembered image is not a reliable comparison record.',de:'Verbinde diesen Punkt mit der vor dem Kauf gespeicherten Notiz. Vergleiche das Sichtbare mit dem genauen Produkt, der Variante und der Messung; ein allgemeiner Name oder eine Erinnerung ist kein verlässlicher Vergleich.',fr:'Reliez ce point à la note conservée avant l’achat. Comparez le résultat visible au produit, à la variante et à la mesure précis ; un nom général ou un souvenir ne constitue pas une comparaison fiable.',es:'Conecta este punto con la nota guardada antes de comprar. Compara el resultado visible con producto, variante y medida precisos; un nombre general o un recuerdo no son una comparación fiable.',it:'Collega questo punto alla nota salvata prima dell’acquisto. Confronta il risultato visibile con prodotto, variante e misura precisi; un nome generico o un ricordo non sono un confronto affidabile.',pt:'Ligue este ponto à nota guardada antes da compra. Compare o resultado visível com produto, variante e medida precisos; um nome geral ou memória não são comparação fiável.',nl:'Koppel dit punt aan de notitie van vóór aankoop. Vergelijk het zichtbare resultaat met het precieze product, de variant en maat; een algemene naam of herinnering is geen betrouwbare vergelijking.',pl:'Połącz ten punkt z notatką sprzed zakupu. Porównaj widoczny wynik z dokładnym produktem, wariantem i wymiarem; ogólna nazwa lub pamięć nie są wiarygodnym porównaniem.'};
const uniformAction={en:'Use the current account screen for the action itself. It is the place that shows what evidence, options and time limits apply to the particular order, warehouse item or parcel at that moment.',de:'Nutze für die konkrete Aktion die aktuelle Kontoansicht. Dort stehen Belege, Optionen und Fristen für die betreffende Bestellung, den Lagerartikel oder das Paket zu diesem Zeitpunkt.',fr:'Utilisez l’écran actuel du compte pour l’action elle-même. Il montre les preuves, options et délais applicables à cette commande, cet article en entrepôt ou ce colis à ce moment-là.',es:'Usa la pantalla actual de cuenta para la acción concreta. Allí se muestran pruebas, opciones y plazos aplicables a ese pedido, artículo de almacén o paquete en ese momento.',it:'Usa la schermata attuale dell’account per l’azione concreta. Mostra prove, opzioni e scadenze applicabili a quell’ordine, articolo in magazzino o pacco in quel momento.',pt:'Use o ecrã atual da conta para a ação concreta. Mostra provas, opções e prazos aplicáveis a essa encomenda, artigo no armazém ou pacote nesse momento.',nl:'Gebruik het actuele accountscherm voor de concrete actie. Daar staan bewijzen, opties en termijnen die op die order, dat magazijnartikel of pakket van toepassing zijn.',pl:'Do konkretnej czynności użyj aktualnego ekranu konta. Pokazuje on dowody, opcje i terminy dotyczące tego zamówienia, artykułu magazynowego lub paczki.'};
const uniformBoundary={en:'The public workflow supports research, warehouse arrival, visible QC checks, consolidation and international shipping choices. It does not guarantee authenticity, every hidden defect, a payment method, a fee, a customs outcome or a delivery time.',de:'Der öffentliche Ablauf beschreibt Recherche, Lagerankunft, sichtbare QC-Prüfung, Bündelung und internationale Versandwahl. Er garantiert weder Echtheit noch jeden verdeckten Fehler, Zahlungsart, Gebühr, Zollergebnis oder Lieferzeit.',fr:'Le parcours public décrit recherche, arrivée en entrepôt, QC visible, regroupement et choix d’envoi international. Il ne garantit ni authenticité, ni chaque défaut caché, ni moyen de paiement, frais, douane ou délai.',es:'El flujo público describe investigación, llegada al almacén, QC visible, consolidación y envío internacional. No garantiza autenticidad, cada defecto oculto, método de pago, comisión, resultado aduanero ni plazo.',it:'Il flusso pubblico descrive ricerca, arrivo in magazzino, QC visibile, consolidamento e spedizione internazionale. Non garantisce autenticità, ogni difetto nascosto, pagamento, costo, dogana o tempo.',pt:'O fluxo público descreve pesquisa, chegada ao armazém, QC visível, consolidação e envio internacional. Não garante autenticidade, todos os defeitos ocultos, pagamento, taxa, alfândega ou prazo.',nl:'De openbare route beschrijft onderzoek, aankomst in magazijn, zichtbare QC, bundeling en internationale verzending. Zij garandeert geen echtheid, elk verborgen gebrek, betaalwijze, toeslag, douane-uitkomst of levertijd.',pl:'Publiczny proces opisuje research, przyjęcie do magazynu, widoczne QC, konsolidację i wysyłkę międzynarodową. Nie gwarantuje autentyczności, każdej ukrytej wady, płatności, opłaty, wyniku celnego ani terminu.'};
const uniformFinal={en:'Final verification',de:'Abschließende Prüfung',fr:'Vérification finale',es:'Verificación final',it:'Verifica finale',pt:'Verificação final',nl:'Laatste controle',pl:'Kontrola końcowa'};
if(article&&audit[code]){const [eyebrow,title,dek]=uniformHeader[code];const body=audit[code].map((v,i)=>{const [h,p]=v.split('|');return `<section><h2>${i+1}. ${h}</h2><p>${p}</p><p>${uniformDecision[code]}</p><p>${uniformAction[code]}</p><p>${uniformBoundary[code]}</p></section>`;}).join('');article.innerHTML=`<header><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="article-dek">${dek}</p><p class="article-note">${uniformBoundary[code]}</p></header>${body}<section><h2>13. ${uniformFinal[code]}</h2><p>${uniformDecision[code]}</p><p>${uniformAction[code]}</p><p>${uniformBoundary[code]}</p><p>${uniformDecision[code]}</p></section>`;}
})();
